package org.nonfood.oilplants.web;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.*;import java.io.*;
@WebServlet("/admin/plants/sample/delete") public class AdminSampleDeleteServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String plant=r.getParameter("plantId");try{WebSupport.requireAdmin(r);long p=Long.parseLong(plant),sample=Long.parseLong(r.getParameter("sampleId"));new PlantDao().removeSample(p,sample);new AuditDao().log(WebSupport.user(r).getId(),"DELETE","oil_sample",sample,"Plant "+p,r.getRemoteAddr());r.getSession().setAttribute("flash","采样记录及其化学组分已删除。");}catch(Exception e){r.getSession().setAttribute("flash","删除采样记录失败："+e.getMessage());}s.sendRedirect(r.getContextPath()+"/admin/plants/form?id="+plant);}}
